@startuml

class Song {
  + Title : string
  + Year : int
  + Length : time
  + Genre : string
}

class Artist {
  + Name : string
  + BirthDate : date
  + Website : string
}

class User {
  + UserID : int
  + Name : string
  + Address : string
}

abstract class UserType {}
class RegularUser extends UserType {}
class BusinessUser extends UserType {}

class VATNumber {
  + Number : string
}

class SongType {}
class Single extends SongType {}
class Hit extends SongType {}

class Album {
  + TrackNumber : int
}

class Suggestion {}

Song "1" -- "1" Artist
RegularUser "0..*" -- "1" Song
BusinessUser "0..*" -- "1" Song
BusinessUser "0..*" -- "1" VATNumber
RegularUser "0..1" -- "*" Album
Album "1..*" -- "1" Hit

@enduml

